program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def runs(line, offset=0):
        result = []
        i = 0
        while i < len(line):
            color = line[i]
            j = i + 1
            while j < len(line) and line[j] == color:
                j += 1
            if color != bg and j - i >= 2:
                result.append((color, i + offset, j + offset))
            i = j
        return result

    # Look for equal-color bars on opposite borders, first in horizontal
    # orientation and then in vertical orientation.
    bar_pair = None
    top = runs(grid[0])
    bottom = runs(grid[-1])
    for a in top:
        for b in bottom:
            if a[0] == b[0]:
                bar_pair = ('horizontal', a, b)
                break
        if bar_pair:
            break
    if bar_pair is None:
        left = runs([grid[r][0] for r in range(h)])
        right = runs([grid[r][-1] for r in range(h)])
        for a in left:
            for b in right:
                if a[0] == b[0]:
                    bar_pair = ('vertical', a, b)
                    break
            if bar_pair:
                break
    if bar_pair is None:
        return [row[:] for row in grid]

    orient, a, b = bar_pair
    bar_color, a0, a1 = a
    _, b0, b1 = b
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != bar_color]

    for r, c, color in markers:
        if orient == 'horizontal':
            idx = c - a0
            if 0 <= idx < a1 - a0 and b0 + idx < b1:
                target = b0 + idx
                for rr in range(h):
                    if out[rr][target] != bar_color:
                        out[rr][target] = color
            # Extend from the first (top) bar toward the marker. Very short
            # one-cell gaps are left unchanged, as in the demonstrations.
            if r - 1 >= 2 and a0 <= c < a1:
                for rr in range(1, r):
                    if out[rr][c] != bar_color:
                        out[rr][c] = color
        else:
            idx = r - a0
            if 0 <= idx < a1 - a0 and b0 + idx < b1:
                target = b0 + idx
                for cc in range(w):
                    if out[target][cc] != bar_color:
                        out[target][cc] = color
            # Extend from the first (left) bar toward the marker.
            if c - 1 >= 2 and a0 <= r < a1:
                for cc in range(1, c):
                    if out[r][cc] != bar_color:
                        out[r][cc] = color

    for r, c, _ in markers:
        out[r][c] = 4
    return out
'''
